class Solution:
    def summaryRanges(self,nums):
        result=[];i=0
        while i<len(nums):
            start=nums[i]
            while i+1<len(nums) and nums[i+1]==nums[i]+1:i+=1
            result.append(str(start) if start==nums[i] else str(start)+'->'+str(nums[i]))
            i+=1
        return result
